  'tape-echo': {
    title: 'TAPE ECHO',
    subtitle: 'Multi-Head Tape Echo with Spring',
    category: 'Essentials',
    sliders: [
      { name: 'Repeat Time', range: '50 to 1000 ms', desc: 'Time between the record head and playback head 1 (50 to 1000 ms); heads 2 and 3 sit at twice and three times this distance. A change glides like a tape motor, so the echoes bend in pitch.' },
      { name: 'Tempo Sync', range: 'Off / 1/4 / 1/8 / 1/16 / 1/4D / 1/8D / 1/4T / 1/8T', desc: 'Locks head 1 to a note at the project tempo (straight, dotted or triplet); heads 2 and 3 follow at 2x and 3x. Off uses Repeat Time.' },
      { name: 'Heads', range: '1 / 2 / 3 / 1+2 / 1+3 / 2+3 / 1+2+3 / 1+R / 1+2+R / 2+3+R / 1+2+3+R / R', desc: 'The classic 12-position selector: which playback heads you hear and feed back (1, 2, 3 and their combinations), the R positions add the spring reverb, and R alone is the reverb without echoes.' },
      { name: 'Intensity', range: '0 to 110%', desc: 'Feedback of the active heads into one shared loop; 100% is unity loop gain in every mode, above it the echo runs away into self-oscillation that the tape saturation keeps bounded.' },
      { name: 'Bass', range: '−12 to +12 dB', desc: 'Low shelf at 250 Hz on the echoes (-12 to +12 dB).' },
      { name: 'Treble', range: '−12 to +12 dB', desc: 'High shelf at 2.5 kHz on the echoes (-12 to +12 dB).' },
      { name: 'Wow/Flutter', range: '0 to 100%', desc: 'Tape wow (two slow sines, up to 2.5 ms) and flutter (two fast sines, up to 0.15 ms) moving every head together, so the repeats waver in pitch.' },
      { name: 'Saturation', range: '0 to 100%', desc: 'Tape drive inside the feedback loop: 0% only rounds very loud repeats, higher values squash and colour every repeat with asymmetric (even) harmonics.' },
      { name: 'Spring', range: '0 to 100%', desc: 'Level of the spring reverb, heard in the R positions of the Heads selector; it is fed with the input and the echoes.' },
      { name: 'Mix', range: '0 to 100%', desc: 'Blend between the dry signal and the echoes (plus the spring).' },
      { name: 'Freeze', range: 'Off / On', desc: 'Stops recording and loops what is on the tape (the length of the longest active head) forever, without fading or building up.' }
    ],
    uses: ['Dub and reggae echoes that build and run away under your hand', 'Rhythmic multi-head patterns from one repeat time', 'Slapback with tape colour on vocals and guitars', 'Spring-drenched surf and ambient washes in the R modes', 'Warbly lo-fi delays with heavy wow, flutter and saturation'],
    properties: 'Signal chain: Input + loop → stereo tape (record head) → playback heads at 1x, 2x, 3x the repeat time (4-point Hermite reads, wow/flutter on all heads, the time glides over ~0.12 s) → heads of the selected mode summed → feedback loop: ÷ number of heads → 12 dB/oct low-pass at 4.5 kHz → asymmetric soft saturation (slope 1 at 0, bounded) → 90 Hz one-pole low cut → × Intensity back onto the tape. Echo output: heads ÷ √(number of heads) → Bass (low shelf 250 Hz) → Treble (high shelf 2.5 kHz) → + spring tank in the R modes (two dispersive 40-stage all-pass springs, 2.2 s decay, fed with input and echoes) → Dry/Wet Mix. Tape length 6.75 s (3 × a dotted quarter at 40 bpm); zero latency.',
    formats: ['JSFX', 'GFX', 'VST3', 'CLAP'],
    shot: 'assets/img/gfx/tape_echo.png',
    video: 'assets/video/tape_echo.mp4',
    studio: true,
    demo: 'tape_echo',
    page: 'plugins/tape-echo/'
  },
